String _sequencerTitle(SequencerEvent v) {
  return switch (v) {
    SequencerEvent_Started() => 'Sequence started',
    SequencerEvent_Paused() => 'Sequence paused',
    SequencerEvent_Resumed() => 'Sequence resumed',
    SequencerEvent_Stopped() => 'Sequence stopped',
    SequencerEvent_Completed() => 'Sequence complete',
    SequencerEvent_Failed() => 'Sequence failed',
    SequencerEvent_NodeStarted() => 'Step started',
    SequencerEvent_NodeCompleted() => 'Step finished',
    SequencerEvent_Progress() => 'Progress',
    SequencerEvent_TargetChanged() => 'Target changed',
    SequencerEvent_TargetCompleted() => 'Target complete',
    SequencerEvent_ExposureStarted() => 'Exposure started',
    SequencerEvent_ExposureCompleted() => 'Exposure complete',
    SequencerEvent_Error() => 'Sequencer error',
    SequencerEvent_MeridianFlipOutcome(outcome: final o) => switch (o) {
      'success' => 'Meridian flip complete',
      'aborted' => 'Meridian flip aborted',
      _ => 'Meridian flip FAILED',
    },
    SequencerEvent_TriggerFired() => 'Trigger fired',
    SequencerEvent_InstructionProgress() => 'Instruction progress',
    SequencerEvent_InstructionProgressStructured() => 'Instruction progress',
    // Typed grading payloads. Surfaced as their own titles so the
    // trigger feed / event log shows "Frame accepted" / "Frame rejected"
    // instead of swallowing them under the generic "Instruction progress"
    // catch-all.
    SequencerEvent_FrameAccepted() => 'Frame accepted',
    SequencerEvent_FrameRejected() => 'Frame rejected',
    SequencerEvent_SchedulerDecision(pickedTargetName: final n) =>
      n == null ? 'Scheduler: no pick' : 'Scheduler: pick',
    SequencerEvent_IntegrationBudget(budgetMet: final met) =>
      met ? 'Budget complete' : 'Budget progress',
    // Recovery Mode — title rendering for the trigger feed /
    // event log. The Run Dashboard banner consumes the same payload via
    // `recoveryEventBridgeProvider` and renders a richer UI; these
    // strings exist so the unified event log doesn't fall back to the
    // generic Object.toString().
    SequencerEvent_RecoveryStarted() => 'Recovery started',
    SequencerEvent_RecoveryProgress() => 'Recovery in progress',
    SequencerEvent_RecoveryCompleted(phase: 'Waiting') => 'Recovery handed off',
    SequencerEvent_RecoveryCompleted() => 'Recovery complete',
    SequencerEvent_RecoveryGaveUp(abortedByUser: final aborted) =>
      aborted ? 'Recovery aborted' : 'Recovery exhausted',
    // Adaptive exposure ("ExposureAdjusted") and any
    // other adaptive-exposure events that haven't been wired into this
    // label switch yet. Fallback to the generic class-name discriminant
    // until each is given a hand-written label.
    SequencerEvent_ExposureAdjusted() => 'Exposure adjusted',
    // Plugin sequence node dispatch.
    SequencerEvent_PluginNodeRequested() => 'Plugin node requested',
    SequencerEvent_PluginNodeProgress() => 'Plugin node progress',
    // Replay Debug — structured executor decision stream.
    SequencerEvent_DecisionLogged() => 'Decision logged',
    // Typed Science / photometry payloads. Surfaced as their own
    // titles so the trigger feed / event log shows the photometry outcome
    // instead of swallowing them under "Instruction progress".
    SequencerEvent_PhotometryFrame(accepted: final ok) =>
      ok ? 'Photometry frame' : 'Photometry frame rejected',
    SequencerEvent_PhotometryCadenceBroken() => 'Cadence broken',
    SequencerEvent_PhotometrySummary() => 'Photometry complete',
    // DepthLock: a Smart Exposure plan stopped early because the filter's
    // depth goal was reached. Its own title so the feed says what ended the
    // plan rather than filing it under "Step finished".
    SequencerEvent_DepthGoalCompleted() => 'Depth goal reached',
  };
}

String _sequencerDetail(SequencerEvent v) {
  return switch (v) {
    SequencerEvent_Started(sequenceName: final n) => n,
    SequencerEvent_Paused() => '',
    SequencerEvent_Resumed() => '',
    SequencerEvent_Stopped() => '',
    SequencerEvent_Completed() => '',
    SequencerEvent_Failed(error: final e) => e,
    SequencerEvent_NodeStarted(nodeType: final t) => t,
    SequencerEvent_NodeCompleted(status: final s) => s,
    SequencerEvent_Progress(current: final c, total: final t) => '$c / $t',
    SequencerEvent_TargetChanged(targetName: final n) => n,
    SequencerEvent_TargetCompleted(targetName: final n) => n,
    SequencerEvent_ExposureStarted(
      frame: final f,
      total: final t,
      filter: final flt,
      durationSecs: final d,
    ) =>
      flt != null && flt.isNotEmpty
          ? '$f/$t · $flt · ${d.toStringAsFixed(1)}s'
          : '$f/$t · ${d.toStringAsFixed(1)}s',
    SequencerEvent_ExposureCompleted(
      frame: final f,
      total: final t,
      durationSecs: final d,
    ) =>
      '$f/$t · ${d.toStringAsFixed(1)}s',
    SequencerEvent_Error(message: final m) => m,
    SequencerEvent_MeridianFlipOutcome(
      targetName: final t,
      outcome: final o,
      attempts: final a,
      durationSecs: final d,
      error: final e,
    ) =>
      o == 'success'
          ? (a > 1
                ? '$t · succeeded on attempt $a · ${d.toStringAsFixed(1)}s'
                : '$t · ${d.toStringAsFixed(1)}s')
          : '$t · after $a attempt${a == 1 ? '' : 's'}: '
                '${e ?? "unknown error"}',
    SequencerEvent_TriggerFired(triggerName: final n, action: final a) =>
      '$n → $a',
    SequencerEvent_InstructionProgress(
      instruction: final i,
      progressPercent: final p,
      detail: final d,
    ) =>
      d.isNotEmpty
          ? '$i: $d (${p.toStringAsFixed(0)}%)'
          : '$i (${p.toStringAsFixed(0)}%)',
    SequencerEvent_InstructionProgressStructured(
      instruction: final i,
      progressPercent: final p,
      detailKind: final k,
    ) =>
      '$i: $k (${p.toStringAsFixed(0)}%)',
    // Single source of truth for the typed grading payload
    // display strings. The dashboard panels render the same wording so
    // the trigger feed + panel always agree.
    SequencerEvent_FrameAccepted(
      frame: final f,
      total: final t,
      hfr: final h,
      acceptedTotal: final acc,
      rejectedTotal: final rej,
    ) =>
      h != null
          ? 'frame $f/$t accepted (HFR ${h.toStringAsFixed(2)}; $acc/${acc + rej} kept)'
          : 'frame $f/$t accepted ($acc/${acc + rej} kept)',
    SequencerEvent_FrameRejected(
      frame: final f,
      total: final t,
      reason: final r,
      consecutiveRejects: final c,
    ) =>
      c > 1
          ? 'frame $f/$t REJECTED ($c× consecutive): $r'
          : 'frame $f/$t REJECTED: $r',
    SequencerEvent_SchedulerDecision(
      decisionCounter: final dc,
      pickedTargetName: final n,
      pickedScore: final s,
      scores: final scores,
    ) =>
      n != null && s != null
          ? 'decision $dc: picked $n (${s.toStringAsFixed(0)}/100, ${scores.length} candidates)'
          : 'decision $dc: no runnable target (${scores.length} candidates)',
    SequencerEvent_IntegrationBudget(
      filter: final flt,
      completedSecs: final cs,
      budgetSecs: final bs,
      budgetMet: final met,
    ) =>
      _integrationBudgetDetail(flt, cs, bs, met),
    // Recovery Mode — single-line detail for the trigger feed.
    // `causeCustomLabel` overrides `causeKind` so a `Custom("dome cable
    // dragging")` recovery surfaces the real reason instead of the bare
    // "Custom" discriminant.
    SequencerEvent_RecoveryStarted(
      causeKind: final kind,
      causeCustomLabel: final custom,
      attemptCount: final a,
      maxAttempts: final maxA,
    ) =>
      '${custom?.isNotEmpty == true ? custom! : kind} '
          '(attempt ${a + 1}/$maxA)',
    SequencerEvent_RecoveryProgress(
      causeKind: final kind,
      causeCustomLabel: final custom,
      attemptCount: final a,
      maxAttempts: final maxA,
      phase: final ph,
    ) =>
      '${custom?.isNotEmpty == true ? custom! : kind} · $ph '
          '(${a == 0 ? "1st" : "${a + 1}th"} of $maxA)',
    SequencerEvent_RecoveryCompleted(
      phase: 'Waiting',
      lastError: final reason,
    ) =>
      reason ?? 'Recovery handed to the meridian flip controller',
    SequencerEvent_RecoveryCompleted(
      causeKind: final kind,
      causeCustomLabel: final custom,
      attemptCount: final a,
    ) =>
      'recovered from ${custom?.isNotEmpty == true ? custom! : kind} '
          'after $a attempt${a == 1 ? "" : "s"}',
    SequencerEvent_RecoveryGaveUp(
      causeKind: final kind,
      causeCustomLabel: final custom,
      attemptCount: final a,
      lastError: final err,
      abortedByUser: final aborted,
    ) =>
      aborted
          ? 'operator aborted ${custom?.isNotEmpty == true ? custom! : kind} '
                'after $a attempt${a == 1 ? "" : "s"}'
          : 'exhausted ${custom?.isNotEmpty == true ? custom! : kind} '
                'after $a attempt${a == 1 ? "" : "s"}'
                '${err != null && err.isNotEmpty ? "; $err" : ""}',
    // Adaptive exposure. Lightweight one-line render
    // showing the nominal/adapted exposure pair and the reason; the
    // dashboard's Adaptive Exposure panel renders the full detail.
    SequencerEvent_ExposureAdjusted(
      nominalSecs: final o,
      adaptedSecs: final a,
      filter: final flt,
      reason: final r,
    ) =>
      flt != null && flt.isNotEmpty
          ? '$flt: ${o.toStringAsFixed(1)}s → ${a.toStringAsFixed(1)}s ($r)'
          : '${o.toStringAsFixed(1)}s → ${a.toStringAsFixed(1)}s ($r)',
    // Plugin node dispatch.
    SequencerEvent_PluginNodeRequested(
      pluginId: final pid,
      nodeTypeId: final tid,
      displayName: final name,
      timeoutSecs: final to,
    ) =>
      '${name?.isNotEmpty == true ? name! : "$pid/$tid"} '
          '(timeout ${to}s)',
    SequencerEvent_PluginNodeProgress(
      pluginId: final pid,
      nodeTypeId: final tid,
      detailJson: final dj,
    ) =>
      dj.isEmpty ? '$pid/$tid' : '$pid/$tid: $dj',
    SequencerEvent_DecisionLogged(
      category: final category,
      summary: final summary,
      sequenceRunId: final runId,
    ) =>
      runId == null ? '$category: $summary' : '$category #$runId: $summary',
    // Typed Science / photometry payloads. The light-curve panel binds
    // to the explicit fields directly; these one-line renders feed the
    // trigger feed / event log so it agrees with the panel wording.
    SequencerEvent_PhotometryFrame(
      targetDesignation: final tgt,
      frame: final f,
      total: final t,
      filter: final flt,
      snr: final snr,
      fwhmArcsec: final fwhm,
      accepted: final ok,
      rejectReason: final reason,
    ) =>
      _photometryFrameDetail(tgt, f, t, flt, snr, fwhm, ok, reason),
    SequencerEvent_PhotometryCadenceBroken(
      frame: final f,
      total: final t,
      gapSecs: final gap,
      maxGapSecs: final maxGap,
      cadenceBreaks: final breaks,
    ) =>
      'frame $f/$t: ${gap.toStringAsFixed(1)}s gap '
          '(max ${maxGap.toStringAsFixed(1)}s); break #$breaks',
    SequencerEvent_PhotometrySummary(
      targetDesignation: final tgt,
      filter: final flt,
      framesCaptured: final frames,
      cadenceBreaks: final breaks,
      lastRejectReason: final reason,
    ) =>
      '$tgt $flt: $frames frames, $breaks cadence breaks'
          '${reason != null && reason.isNotEmpty ? ", last reject: $reason" : ""}',
    SequencerEvent_DepthGoalCompleted(
      filterName: final flt,
      score: final score,
      threshold: final threshold,
      evidenceFrames: final evidence,
      confirmationFrames: final confirming,
    ) =>
      depthGoalCompletedDetail(
        filterName: flt,
        score: score,
        threshold: threshold,
        evidenceFrames: evidence,
        confirmationFrames: confirming,
      ),
  };
}

/// One line for a Smart Exposure plan that ended on its depth goal.
///
/// Shared rather than inlined in the switch arm because the run dashboard
/// and the session report render the same sentence — a plan that stopped
/// early has to read identically wherever the operator finds it.
String depthGoalCompletedDetail({
  required String filterName,
  required double score,
  required double threshold,
  required int evidenceFrames,
  required int confirmationFrames,
}) =>
    '$filterName reached its depth goal '
    '(score ${score.toStringAsFixed(1)} >= ${threshold.toStringAsFixed(1)}, '
    '$evidenceFrames exposure${evidenceFrames == 1 ? '' : 's'}, '
    '$confirmationFrames confirming)';

/// Title for a DepthLock event. The goal store's own events, not the
/// sequencer's: they arrive while nothing is running too, whenever an
/// archival frame is offered to a goal.
String _depthLockTitle(DepthLockEvent v) {
  return switch (v) {
    DepthLockEvent_GoalUpdated(state: final state) => switch (state) {
      'achieved' => 'Depth goal achieved',
      'confirmationPending' => 'Depth goal confirming',
      'unreliable' => 'Depth evidence unreliable',
      _ => 'Depth goal progress',
    },
    DepthLockEvent_EvidenceRejected() => 'Depth evidence rejected',
    DepthLockEvent_AnalysisDropped() => 'Depth analysis dropped',
    DepthLockEvent_GoalChanged(change: final change) => 'Depth goal $change',
  };
}

String _depthLockDetail(DepthLockEvent v) {
  return switch (v) {
    DepthLockEvent_GoalUpdated(
      filterName: final filter,
      score: final score,
      threshold: final threshold,
      evidenceFrames: final evidence,
      reason: final reason,
    ) =>
      score == null
          ? '$filter: $reason'
          : '$filter: score ${score.toStringAsFixed(1)} / '
                '${threshold.toStringAsFixed(1)} over $evidence '
                'exposure${evidence == 1 ? '' : 's'} — $reason',
    DepthLockEvent_EvidenceRejected(
      sourcePath: final path,
      reason: final reason,
    ) =>
      '$reason ($path)',
    DepthLockEvent_AnalysisDropped(
      sourcePath: final path,
      reason: final reason,
    ) =>
      '$reason ($path)',
    DepthLockEvent_GoalChanged(goalId: final id, revision: final revision) =>
      '$id (revision $revision)',
  };
}

/// Single-line render of a PhotometryFrame event for the trigger feed /
/// event log. Pulled out of the switch arm because Dart switch-expressions
/// don't allow statements inside the arm body.
String _photometryFrameDetail(
  String target,
  int frame,
  int total,
  String filter,
  double? snr,
  double? fwhm,
  bool accepted,
  String? rejectReason,
) {
  final outcome = accepted
      ? 'PASS'
      : (rejectReason != null && rejectReason.isNotEmpty
            ? 'REJECT ($rejectReason)'
            : 'REJECT');
  final snrText = snr != null ? 'SNR ${snr.toStringAsFixed(1)}' : 'SNR —';
  final fwhmText = fwhm != null ? 'FWHM ${fwhm.toStringAsFixed(2)}"' : 'FWHM —';
  return '$target frame $frame/$total $filter · $snrText · $fwhmText · $outcome';
}

/// Single-line render of an IntegrationBudget event. Pulled out
/// of the switch arm because Dart switch-expressions don't allow `if`
/// inside the arm body.
String _integrationBudgetDetail(
  String filter,
  double completedSecs,
  double budgetSecs,
  bool budgetMet,
) {
  final label = filter.isEmpty ? 'total' : filter;
  if (budgetMet) {
    return '$label budget met (${completedSecs.toStringAsFixed(0)}s)';
  }
  if (budgetSecs > 0.0) {
    return '$label ${completedSecs.toStringAsFixed(0)}s / ${budgetSecs.toStringAsFixed(0)}s';
  }
  return '$label ${completedSecs.toStringAsFixed(0)}s';
}

String _safetyTitle(SafetyEvent v) {
  return switch (v) {
    SafetyEvent_WeatherUnsafe() => 'Weather unsafe',
    SafetyEvent_WeatherSafe() => 'Weather safe',
    SafetyEvent_EmergencyStop() => 'Emergency stop',
    SafetyEvent_ParkInitiated() => 'Park initiated',
    SafetyEvent_ParkCompleted() => 'Park complete',
  };
}

String _safetyDetail(SafetyEvent v) {
  return switch (v) {
    SafetyEvent_WeatherUnsafe(reason: final r) => r,
    SafetyEvent_WeatherSafe() => '',
    SafetyEvent_EmergencyStop(reason: final r) => r,
    SafetyEvent_ParkInitiated(reason: final r) => r,
    SafetyEvent_ParkCompleted() => '',
  };
}

String _systemTitle(SystemEvent v) {
  return switch (v) {
    SystemEvent_Initialized() => 'System ready',
    SystemEvent_ShuttingDown() => 'Shutting down',
    SystemEvent_Error() => 'System error',
    SystemEvent_DiskSpaceLow() => 'Disk space low',
    SystemEvent_Notification(title: final t) => t,
    SystemEvent_EventsDropped() => 'Events dropped',
  };
}

String _systemDetail(SystemEvent v) {
  return switch (v) {
    SystemEvent_Initialized() => '',
    SystemEvent_ShuttingDown() => '',
    SystemEvent_Error(message: final m) => m,
    SystemEvent_DiskSpaceLow(availableGb: final gb) =>
      '${gb.toStringAsFixed(1)} GB free',
    SystemEvent_Notification(message: final m, level: final lvl) =>
      lvl.isNotEmpty ? '$m ($lvl)' : m,
    SystemEvent_EventsDropped(droppedCount: final n, totalDropped: final tot) =>
      '$n events dropped (total: $tot)',
  };
}
